.darma-loader-tw-pin-drop { position: relative; display: inline-block; width: var(--loader-size, 64px); height: var(--loader-size, 64px); }
.darma-loader-tw-pin-drop .darma-loader-tw-pin-drop__pin { position: absolute; left: 50%; top: 10%; width: calc(var(--loader-size, 64px) * .44); height: calc(var(--loader-size, 64px) * .44); margin-left: calc(var(--loader-size, 64px) * -.22); border-radius: 50% 50% 50% 0; background: var(--loader-color, #e11d48); animation: darma-loader-tw-pin-drop-twDrop calc(var(--loader-speed, 1s) * 1.8) cubic-bezier(.5, 0, .5, 1) infinite; }
.darma-loader-tw-pin-drop .darma-loader-tw-pin-drop__pin::after { content: ''; position: absolute; left: 28%; top: 28%; width: 44%; height: 44%; border-radius: 9999px; background: color-mix(in srgb, #ffffff 78%, var(--loader-color, #e11d48)); }
.darma-loader-tw-pin-drop .darma-loader-tw-pin-drop__shadow { position: absolute; left: 50%; bottom: 10%; width: calc(var(--loader-size, 64px) * .34); height: calc(var(--loader-size, 64px) * .09); margin-left: calc(var(--loader-size, 64px) * -.17); border-radius: 9999px; background: color-mix(in srgb, var(--loader-color, #e11d48) 38%, transparent); animation: darma-loader-tw-pin-drop-twShadow calc(var(--loader-speed, 1s) * 1.8) cubic-bezier(.5, 0, .5, 1) infinite; }
@keyframes darma-loader-tw-pin-drop-twDrop { 0%, 100% { transform: translateY(-16%) rotate(-45deg); } 50% { transform: translateY(20%) rotate(-45deg); } }
@keyframes darma-loader-tw-pin-drop-twShadow { 0%, 100% { transform: scale(.7); opacity: .3; } 50% { transform: scale(1); opacity: .75; } }

